// ==UserScript==
// @name         DSA Tracker Live Sync
// @namespace    dsa-tracker
// @version      __VERSION__
// @description  Syncs accepted LeetCode submissions to DSA Tracker. Pairs automatically when you open the tracker.
// @match        https://leetcode.com/*
// @include      http://localhost:*/*
// @include      http://127.0.0.1:*/*
// __APP_INCLUDES__
// @grant        GM_xmlhttpRequest
// @grant        GM_getValue
// @grant        GM_setValue
// @grant        unsafeWindow
// @connect      *
// @run-at       document-start
// ==/UserScript==

/*
 * GENERATED by scripts/build-extension.mjs from extension/userscript.template.js
 * and extension/leetcode-hook.js. Edit those, not the built file.
 *
 * Sync-only build of the extension for browsers where the extension can't be
 * installed from a store. On leetcode.com it injects the same network hook as
 * the extension; on the tracker it answers PING/PAIR so the app pairs it.
 */
(function () {
  "use strict";

  var VERSION = "__VERSION__";
  var HOOK_SOURCE = "DSA_TRACKER_LC_HOOK";
  var PAGE = typeof unsafeWindow !== "undefined" ? unsafeWindow : window;
  var isLeetCode = /(^|\.)leetcode\.com$/.test(location.hostname);

  var get = function (k, d) {
    var v = GM_getValue(k);
    return v === undefined ? d : v;
  };
  var set = function (k, v) {
    GM_setValue(k, v);
  };

  // --------------------------------------------------------------- tracker
  var postToTracker = function (report) {
    return new Promise(function (resolve, reject) {
      var pairing = get("pairing", null);
      if (!pairing || !pairing.token) {
        var e = new Error("Open DSA Tracker while signed in to pair.");
        e.unpaired = true;
        reject(e);
        return;
      }
      var parseMs = function (v) {
        var m = String(v || "").match(/([\d.]+)\s*(ms|s)?/i);
        return m ? Math.round(Number(m[1]) * (m[2] && m[2].toLowerCase() === "s" ? 1000 : 1)) : undefined;
      };
      var parseKb = function (v) {
        var m = String(v || "").match(/([\d.]+)\s*(kb|mb|gb)?/i);
        if (!m) return undefined;
        var u = (m[2] || "mb").toLowerCase();
        return Math.round(Number(m[1]) * (u === "gb" ? 1048576 : u === "mb" ? 1024 : 1));
      };
      var diff = String(report.difficulty || "").toUpperCase();
      var body = {
        submissionId: String(report.submissionId),
        slug: String(report.slug).toLowerCase(),
        verdict: "ACCEPTED",
        submittedAt: new Date((Number(report.timestamp) || Math.floor(Date.now() / 1000)) * 1000).toISOString(),
        runtimeMs: parseMs(report.runtime),
        memoryKb: parseKb(report.memory),
        title: report.title || undefined,
        difficulty: ["EASY", "MEDIUM", "HARD"].indexOf(diff) >= 0 ? diff : undefined,
        lang: report.lang || undefined,
        code: report.code ? String(report.code).slice(0, 100000) : undefined,
        runtimePercentile: typeof report.runtimePercentile === "number" ? report.runtimePercentile : undefined,
        memoryPercentile: typeof report.memoryPercentile === "number" ? report.memoryPercentile : undefined,
      };
      GM_xmlhttpRequest({
        method: "POST",
        url: pairing.apiBase + "/extension/sync",
        headers: { "Content-Type": "application/json", Authorization: "Bearer " + pairing.token },
        data: JSON.stringify(body),
        onload: function (res) {
          if (res.status === 401) {
            set("pairing", null);
            var e = new Error("Pairing expired");
            e.unpaired = true;
            reject(e);
          } else if (res.status >= 400) {
            var bad = new Error("Sync failed (" + res.status + ")");
            bad.malformed = res.status === 400 || res.status === 404;
            reject(bad);
          } else {
            set("lastSync", { at: Date.now(), slug: report.slug, title: report.title || report.slug });
            resolve();
          }
        },
        onerror: function () {
          reject(new Error("Tracker unreachable"));
        },
      });
    });
  };

  var enqueue = function (report) {
    var q = get("queue", []).filter(function (i) {
      return i.submissionId !== report.submissionId;
    });
    q.push(report);
    set("queue", q.slice(-50));
  };

  var flushQueue = function () {
    var q = get("queue", []);
    if (!q.length) return;
    set("queue", []);
    q.forEach(function (item) {
      postToTracker(item).catch(function (e) {
        if (!e.malformed) enqueue(item);
      });
    });
  };

  // -------------------------------------------------------------- leetcode
  if (isLeetCode) {
    var toast = function (text, ok) {
      var el = document.createElement("div");
      el.textContent = text;
      el.style.cssText =
        "position:fixed;right:20px;bottom:20px;z-index:2147483647;padding:10px 14px;border-radius:10px;" +
        "font:600 13px/1.3 system-ui,sans-serif;color:#fff;box-shadow:0 10px 30px rgba(0,0,0,.35);background:" +
        (ok ? "#059669" : "#b45309");
      (document.body || document.documentElement).appendChild(el);
      setTimeout(function () {
        el.remove();
      }, 3800);
    };

    // Run the network hook in the page itself (LeetCode allows inline scripts).
    var s = document.createElement("script");
    s.textContent = __HOOK__;
    (document.head || document.documentElement).appendChild(s);
    s.remove();

    PAGE.addEventListener("message", function (event) {
      var data = event.data;
      if (!data || data.source !== HOOK_SOURCE || data.type !== "ACCEPTED") return;
      var report = JSON.parse(JSON.stringify(data.data));
      postToTracker(report)
        .then(function () {
          toast("✓ Synced “" + (report.title || report.slug) + "” to DSA Tracker", true);
        })
        .catch(function (e) {
          if (e.malformed) return;
          enqueue(report);
          toast(e.unpaired ? "Accepted! Open DSA Tracker to finish syncing." : "Accepted! Will sync when the tracker is reachable.", false);
        });
    });
    flushQueue();
    return;
  }

  // --------------------------------------------------------------- tracker
  var REQUEST_DOM_EVENT = "DSA_TRACKER_EXTENSION_REQUEST_DOM";
  var RESPONSE_DOM_EVENT = "DSA_TRACKER_EXTENSION_RESPONSE_DOM";
  var READY_DOM_EVENT = "DSA_TRACKER_EXTENSION_READY";

  var respond = function (requestId, ok, payload, error) {
    document.dispatchEvent(
      new CustomEvent(RESPONSE_DOM_EVENT, {
        detail: JSON.stringify({ source: "DSA_TRACKER_EXTENSION", requestId: requestId, ok: ok, payload: payload, error: error }),
      }),
    );
  };

  document.addEventListener(REQUEST_DOM_EVENT, function (event) {
    var d;
    try {
      d = typeof event.detail === "string" ? JSON.parse(event.detail) : event.detail;
    } catch (e) {
      return;
    }
    if (!d || d.source !== "DSA_TRACKER_APP" || !d.requestId) return;
    var pairing = get("pairing", null);
    if (d.action === "PING") {
      respond(d.requestId, true, {
        installed: true,
        version: VERSION,
        kind: "userscript",
        capabilities: ["sync"],
        paired: Boolean(pairing && pairing.token),
        leetcodeSignedIn: true,
        pendingSyncs: get("queue", []).length,
        lastSync: get("lastSync", null),
      });
    } else if (d.action === "PAIR") {
      var token = d.payload && d.payload.token;
      if (typeof token !== "string" || token.indexOf("dsat_") !== 0) {
        respond(d.requestId, false, null, "Invalid pairing token");
        return;
      }
      set("pairing", { token: token, apiBase: location.origin + "/api", pairedAt: Date.now() });
      respond(d.requestId, true, { paired: true });
      flushQueue();
    } else {
      respond(d.requestId, false, null, "Not available in the userscript. Install the full extension for this.");
    }
  });

  var announce = function () {
    document.documentElement.setAttribute("data-dsa-extension", VERSION);
    document.dispatchEvent(new CustomEvent(READY_DOM_EVENT, { detail: JSON.stringify({ source: "DSA_TRACKER_EXTENSION", version: VERSION }) }));
  };
  announce();
  document.addEventListener("DOMContentLoaded", announce, { once: true });
})();
